  `else
    attr_test = 1'b0;
  `endif
    attr_err = 1'b0;
    #1;
    trig_attr = ~trig_attr;
  end
`endif

`ifdef XIL_XECLIB
  assign ACTIVE_DUTYCYCLE_BIN = ACTIVE_DUTYCYCLE_REG * 1000;
  
  assign TOGGLE_RATE_BIN = TOGGLE_RATE_REG * 1000;
  
`else
  always @ (trig_attr) begin
  #1;
  ACTIVE_DUTYCYCLE_BIN = ACTIVE_DUTYCYCLE_REG * 1000;
  
  TOGGLE_RATE_BIN = TOGGLE_RATE_REG * 1000;
  
  end
`endif

`ifndef XIL_XECLIB
  always @ (trig_attr) begin
    #1;
    if ((attr_test == 1'b1) ||
        (ACTIVE_DUTYCYCLE_REG < 0.000 || ACTIVE_DUTYCYCLE_REG > 100.000)) begin
      $display("Error: [Unisim %s-101] ACTIVE_DUTYCYCLE attribute is set to %f.  Legal values for this attribute are 0.000 to 100.000. Instance: %m", MODULE_NAME, ACTIVE_DUTYCYCLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CH0_NUM_TAPS_REG != "16") &&
         (CH0_NUM_TAPS_REG != "0") &&
         (CH0_NUM_TAPS_REG != "4") &&
         (CH0_NUM_TAPS_REG != "8") &&
         (CH0_NUM_TAPS_REG != "12"))) begin
      $display("Error: [Unisim %s-102] CH0_NUM_TAPS attribute is set to %s.  Legal values for this attribute are 16, 0, 4, 8 or 12. Instance: %m", MODULE_NAME, CH0_NUM_TAPS_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CH1_NUM_TAPS_REG != "16") &&
         (CH1_NUM_TAPS_REG != "0") &&
         (CH1_NUM_TAPS_REG != "4") &&
         (CH1_NUM_TAPS_REG != "8") &&
         (CH1_NUM_TAPS_REG != "12"))) begin
      $display("Error: [Unisim %s-103] CH1_NUM_TAPS attribute is set to %s.  Legal values for this attribute are 16, 0, 4, 8 or 12. Instance: %m", MODULE_NAME, CH1_NUM_TAPS_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CH2_NUM_TAPS_REG != "16") &&
         (CH2_NUM_TAPS_REG != "0") &&
         (CH2_NUM_TAPS_REG != "4") &&
         (CH2_NUM_TAPS_REG != "8") &&
         (CH2_NUM_TAPS_REG != "12"))) begin
      $display("Error: [Unisim %s-104] CH2_NUM_TAPS attribute is set to %s.  Legal values for this attribute are 16, 0, 4, 8 or 12. Instance: %m", MODULE_NAME, CH2_NUM_TAPS_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((CH3_NUM_TAPS_REG != "16") &&
         (CH3_NUM_TAPS_REG != "0") &&
         (CH3_NUM_TAPS_REG != "4") &&
         (CH3_NUM_TAPS_REG != "8") &&
         (CH3_NUM_TAPS_REG != "12"))) begin
      $display("Error: [Unisim %s-105] CH3_NUM_TAPS attribute is set to %s.  Legal values for this attribute are 16, 0, 4, 8 or 12. Instance: %m", MODULE_NAME, CH3_NUM_TAPS_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((FIR_COEFF_TYPE_REG != "REAL") &&
         (FIR_COEFF_TYPE_REG != "COMPLEX"))) begin
      $display("Error: [Unisim %s-106] FIR_COEFF_TYPE attribute is set to %s.  Legal values for this attribute are REAL or COMPLEX. Instance: %m", MODULE_NAME, FIR_COEFF_TYPE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((MAX_FIR_LENGTH_REG != "16") &&
         (MAX_FIR_LENGTH_REG != "8") &&
         (MAX_FIR_LENGTH_REG != "32") &&
         (MAX_FIR_LENGTH_REG != "64"))) begin
      $display("Error: [Unisim %s-107] MAX_FIR_LENGTH attribute is set to %s.  Legal values for this attribute are 16, 8, 32 or 64. Instance: %m", MODULE_NAME, MAX_FIR_LENGTH_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((MODE_REG != "CHANNELIZER RX") &&
         (MODE_REG != "CHANNELIZER TX") &&
         (MODE_REG != "FIR FILTER") &&
         (MODE_REG != "OVERSAMPLED CHANNELIZER RX") &&
         (MODE_REG != "OVERSAMPLED CHANNELIZER TX"))) begin
      $display("Error: [Unisim %s-108] MODE attribute is set to %s.  Legal values for this attribute are CHANNELIZER RX, CHANNELIZER TX, FIR FILTER, OVERSAMPLED CHANNELIZER RX or OVERSAMPLED CHANNELIZER TX. Instance: %m", MODULE_NAME, MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((NUMBER_INSTANCE_REG < 1) || (NUMBER_INSTANCE_REG > 4))) begin
      $display("Error: [Unisim %s-109] NUMBER_INSTANCE attribute is set to %d.  Legal values for this attribute are 1 to 4. Instance: %m", MODULE_NAME, NUMBER_INSTANCE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((SAMPLE_RATE_REG != "1") &&
         (SAMPLE_RATE_REG != "2") &&
         (SAMPLE_RATE_REG != "4"))) begin
      $display("Error: [Unisim %s-110] SAMPLE_RATE attribute is set to %s.  Legal values for this attribute are 1, 2 or 4. Instance: %m", MODULE_NAME, SAMPLE_RATE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((SPARE_REG < 0) || (SPARE_REG > 1023))) begin
      $display("Error: [Unisim %s-111] SPARE attribute is set to %d.  Legal values for this attribute are 0 to 1023. Instance: %m", MODULE_NAME, SPARE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        (TOGGLE_RATE_REG < 0.000 || TOGGLE_RATE_REG > 100.000)) begin
      $display("Error: [Unisim %s-112] TOGGLE_RATE attribute is set to %f.  Legal values for this attribute are 0.000 to 100.000. Instance: %m", MODULE_NAME, TOGGLE_RATE_REG);
      attr_err = 1'b1;
    end
    
    if (attr_err == 1'b1) #1 $finish;
  end
`endif



